from decimal import Decimal


def format_balance(amount: Decimal, symbol: str = "$") -> str:
    return f"{symbol}{amount:,.2f}"


def statement(lines: list[tuple[str, Decimal]]) -> str:
    width = max((len(name) for name, _ in lines), default=0)
    return "\n".join(f"{name:<{width}}  {format_balance(value)}" for name, value in lines)

from dataclasses import dataclass, field
from decimal import Decimal


@dataclass
class Ledger:
    entries: list[tuple[str, Decimal]] = field(default_factory=list)

    def post(self, account: str, amount: Decimal) -> None:
        self.entries.append((account, amount))

    def balance(self, account: str) -> Decimal:
        return sum((a for name, a in self.entries if name == account), Decimal(0))
